#!/bin/sh
# Type-checks the plugin's hooks module against the declarations of the
# installed Claude Code build. The engine writes that declaration file only
# when it loads a mod, so a missing copy is generated by one headless call.
set -u

root=$(cd "$(dirname "$0")/.." && pwd)
cache="$root/.cache/claude-code-types"

command -v claude >/dev/null 2>&1 || {
  echo "typecheck:mods: claude is not on PATH" >&2
  exit 1
}
version=$(claude --version | awk '{print $1}')
[ -n "$version" ] || {
  echo "typecheck:mods: claude --version printed nothing" >&2
  exit 1
}

mkdir -p "$cache"
if [ ! -f "$cache/$version.d.ts" ]; then
  scratch=$(mktemp -d)
  (cd "$scratch" && claude -p "/plugin-authoring Reply with the single word ok." --model haiku >/dev/null 2>&1)
  rm -rf "$scratch"
  found=$(find "/tmp/claude-$(id -u)/bundled-skills/$version" -name claude-code.d.ts -exec ls -t {} + 2>/dev/null | head -n 1)
  [ -n "$found" ] || {
    echo "typecheck:mods: no claude-code.d.ts under /tmp/claude-$(id -u)/bundled-skills/$version" >&2
    exit 1
  }
  cp "$found" "$cache/$version.d.ts"
fi

cp "$cache/$version.d.ts" "$cache/current.d.ts"
cd "$root" && bunx tsc -p tsconfig.mods.json
